// writeFixtures generates missing fixtures (never overwrites one):
//
//	go test -tags fts5 ./internal/embed/cache -run TestCacheWriteFixtures -write-fixtures
var writeFixtures = flag.Bool("write-fixtures", false, "write missing testdata/migrations/cache-v*.sql fixtures")

func fixturePath(v int) string {
	return filepath.Join("testdata", "migrations", fmt.Sprintf("cache-v%d.sql", v))
}

// TestCacheSteps: the steps are well-formed and declare the effects listed here.
func TestCacheSteps(t *testing.T) {
	if err := migrations.Check(stepPrefix); err != nil {
		t.Fatal(err)
	}
	want := []struct {
		id     string
		effect migrate.Effect
	}{
		{"cache/0001-baseline", migrate.EffectNone},
	}
	if len(migrations) != len(want) || migrations.Target() != SchemaVersion {
		t.Fatalf("%d steps (Target %d, SchemaVersion %d); the effect table lists %d", len(migrations), migrations.Target(), SchemaVersion, len(want))
	}
	for i, w := range want {
		if got := migrations[i]; got.ID != w.id || got.Effect != w.effect {
			t.Errorf("step %d = (%s, %v), want (%s, %v)", i, got.ID, got.Effect, w.id, w.effect)
		}
	}
}

// TestCacheReplay: a cache built one version at a time equals a fresh Open and Verify's
// reference; every fixture verifies at its version and upgrades to one that verifies, keeping
// its rows readable.
func TestCacheReplay(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "c.sqlite")
	c, err := Open(ctx, path)
	if err != nil {
		t.Fatal(err)
	}
	c.Close()
	got := schemaAt(t, path)
	want, err := freshSchema(ctx, SchemaVersion)
	if err != nil {
		t.Fatal(err)
	}
	if !slices.Equal(got, want) {
		t.Errorf("fresh Open schema %q, reference %q", got, want)
	}
	for v := 1; v <= SchemaVersion; v++ {
		t.Run(fmt.Sprintf("fixture v%d", v), func(t *testing.T) {
			path := loadFixture(t, v)
			a := NewArtefact(path)
			if err := a.Verify(ctx); err != nil {
				t.Fatalf("fixture v%d does not match the steps (was an old step edited?): %v", v, err)
			}
			if _, err := a.Apply(ctx); err != nil {
				t.Fatal(err)
			}
			if err := a.Verify(ctx); err != nil {
				t.Fatal(err)
			}
			c, err := Open(ctx, path)
			if err != nil {
				t.Fatal(err)
			}
			defer c.Close()
			got, err := c.Get(ctx, "BAAI/bge-small-en-v1.5", 4, []string{"journal mode wal", "missing"})
			if err != nil || !slices.Equal(got[0], []float32{1, 0, 0.5, 0}) || got[1] != nil {
				t.Errorf("Get on the upgraded fixture = %v, %v", got, err)
			}
		})
	}
}

// TestCacheWriteFixtures writes missing fixtures under -write-fixtures; otherwise checks each
// version has one.
func TestCacheWriteFixtures(t *testing.T) {
	ctx := context.Background()
	for v := 1; v <= SchemaVersion; v++ {
		_, err := os.Stat(fixturePath(v))
		switch {
		case err == nil:
			continue
		case !errors.Is(err, fs.ErrNotExist):
			t.Fatal(err)
		case !*writeFixtures:
			t.Errorf("no fixture for v%d: run with -write-fixtures and check it in", v)
			continue
		}
		path := filepath.Join(t.TempDir(), "c.sqlite")
		c, err := Open(ctx, path)
		if err != nil {
			t.Fatal(err)
		}
		if err := c.Put(ctx, "BAAI/bge-small-en-v1.5", 4, []string{"journal mode wal", "checkpoint starvation"},
			[][]float32{{1, 0, 0.5, 0}, {0, 1, 0, 0.25}}); err != nil {
			t.Fatal(err)
		}
		if err := c.Put(ctx, "nomic-embed-text", 2, []string{"journal mode wal"}, [][]float32{{0.5, 0.5}}); err != nil {
			t.Fatal(err)
		}
		c.Close()
		if err := os.MkdirAll(filepath.Dir(fixturePath(v)), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(fixturePath(v), []byte(dump(t, path, v)), 0o644); err != nil {
			t.Fatal(err)
		}
		t.Logf("wrote %s", fixturePath(v))
	}
}

// dump renders the cache as the SQL that rebuilds it: version, CREATEs, then rows as quote()
// literals.
func dump(t *testing.T, path string, v int) string {
	t.Helper()
	db := plainDB(t, path)
	var b strings.Builder
	fmt.Fprintf(&b, "-- kb embedding cache fixture at schema v%d. Generated by TestCacheWriteFixtures; NEVER EDIT OR REGENERATE.\n", v)
	fmt.Fprintf(&b, "PRAGMA user_version = %d;\n", v)
	rows, err := db.Query("SELECT sql FROM sqlite_schema WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%' ORDER BY rowid")
	if err != nil {
		t.Fatal(err)
	}
	for rows.Next() {
		var s string
		if err := rows.Scan(&s); err != nil {
			t.Fatal(err)
		}
		b.WriteString(s + ";\n")
	}
	rows.Close()
	rows, err = db.Query("SELECT quote(model) || ',' || quote(dim) || ',' || quote(hash) || ',' || quote(vec) FROM emb ORDER BY model, dim, hash")
	if err != nil {
		t.Fatal(err)
	}
	for rows.Next() {
		var s string
		if err := rows.Scan(&s); err != nil {
			t.Fatal(err)
		}
		fmt.Fprintf(&b, "INSERT INTO emb (model, dim, hash, vec) VALUES (%s);\n", s)
	}
	rows.Close()
	return b.String()
}

func loadFixture(t *testing.T, v int) string {
	t.Helper()
	text, err := os.ReadFile(fixturePath(v))
	if err != nil {
		t.Fatalf("read fixture (generate it with -write-fixtures): %v", err)
	}
	path := filepath.Join(t.TempDir(), "c.sqlite")
	if _, err := plainDB(t, path).Exec(string(text)); err != nil {
		t.Fatalf("load fixture: %v", err)
	}
	return path
}

func plainDB(t *testing.T, path string) *sql.DB {
	t.Helper()
	db, err := sql.Open("sqlite3", path)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { db.Close() })
	return db
}

func schemaAt(t *testing.T, path string) []string {
	t.Helper()
	s, err := schemaOf(context.Background(), plainDB(t, path))
	if err != nil {
		t.Fatal(err)
	}
	return s
}

func setVersion(t *testing.T, path string, v int) {
	t.Helper()
	if _, err := plainDB(t, path).Exec(fmt.Sprintf("PRAGMA user_version = %d", v)); err != nil {
		t.Fatal(err)
	}
}

// TestCacheArtefact is the adapter's decision table: status, apply, verify and backup for each
// state of the file.
func TestCacheArtefact(t *testing.T) {
	ctx := context.Background()
	missing := func(t *testing.T) string { return filepath.Join(t.TempDir(), "sub", "c.sqlite") }
	current := func(t *testing.T) string { return loadFixture(t, SchemaVersion) }
	withV := func(v int) func(t *testing.T) string {
		return func(t *testing.T) string { p := loadFixture(t, SchemaVersion); setVersion(t, p, v); return p }
	}
	garbage := func(t *testing.T) string {
		p := filepath.Join(t.TempDir(), "c.sqlite")
		if err := os.WriteFile(p, []byte(strings.Repeat("garbage ", 300)), 0o644); err != nil {
			t.Fatal(err)
		}
		return p
	}
	drift := func(t *testing.T) string {
		p := current(t)
		if _, err := plainDB(t, p).Exec("CREATE TABLE stray (x)"); err != nil {
			t.Fatal(err)
		}
		return p
	}
	const ok = errs.Kind(-1)
	for _, tc := range []struct {
		name                  string
		setup                 func(t *testing.T) string
		statusKind            errs.Kind
		wantCur, wantPend     int
		applyKind, verifyKind errs.Kind // verify after apply
		backupKind            errs.Kind
	}{
		{"missing", missing, ok, 0, 1, ok, ok, errs.NotFound},
		{"current", current, ok, 1, 0, ok, ok, ok},
		{"newer", withV(SchemaVersion + 1), ok, 2, 0, errs.Conflict, errs.Conflict, ok},
		{"negative", withV(-1), errs.Conflict, 0, 0, errs.Conflict, errs.Conflict, ok},
		{"not a database", garbage, errs.Conflict, 0, 0, errs.Conflict, errs.Conflict, errs.Conflict},
		{"schema drift", drift, ok, 1, 0, ok, errs.Conflict, ok},
	} {
		t.Run(tc.name, func(t *testing.T) {
			path := tc.setup(t)
			a := NewArtefact(path)
			st, err := a.Status(ctx)
			if !kindIs(err, tc.statusKind) {
				t.Fatalf("Status err = %v, want kind %v", err, tc.statusKind)
			}
			if err == nil && (st.Artefact != ArtefactName || st.Current != tc.wantCur || len(st.Pending) != tc.wantPend || st.Target != SchemaVersion) {
				t.Errorf("Status = %+v", st)
			}
			if tc.name == "missing" {
				if _, err := os.Stat(path); err == nil {
					t.Error("Status created the file")
				}
			}
			if !kindIs(a.Backup(ctx, path+".bak"), tc.backupKind) {
				t.Errorf("Backup kind, want %v", tc.backupKind)
			}
			if _, err := a.Apply(ctx); !kindIs(err, tc.applyKind) {
				t.Errorf("Apply err = %v, want kind %v", err, tc.applyKind)
			}
			if err := a.Verify(ctx); !kindIs(err, tc.verifyKind) {
				t.Errorf("Verify err = %v, want kind %v", err, tc.verifyKind)
			}
		})
	}
	if err := NewArtefact(filepath.Join(t.TempDir(), "none")).Verify(ctx); !kindIs(err, errs.NotFound) {
		t.Errorf("Verify of a missing file: %v", err)
	}
}

func kindIs(err error, k errs.Kind) bool {
	if k < 0 {
		return err == nil
	}
	return err != nil && errs.KindOf(err) == k
}

// TestCacheRun: migrate.Run creates a missing cache without a backup, and refuses a newer one.
func TestCacheRun(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "c.sqlite")
	rep, err := migrate.Run(ctx, []migrate.Artefact{NewArtefact(path)}, migrate.Options{})
	if err != nil || rep.Artefacts[0].Backup != "" || len(rep.Artefacts[0].Applied) != 1 {
		t.Fatalf("Run on a missing cache = %+v, %v", rep, err)
	}
	setVersion(t, path, SchemaVersion+1)
	if _, err := migrate.Run(ctx, []migrate.Artefact{NewArtefact(path)}, migrate.Options{}); errs.KindOf(err) != errs.Conflict {
		t.Errorf("Run on a newer cache: %v", err)
	}
}

// TestCacheWrapKinds: each class of failure maps to its kind.
func TestCacheWrapKinds(t *testing.T) {
	cancelled, cancel := context.WithCancel(context.Background())
	cancel()
	bg := context.Background()
	for _, tc := range []struct {
		ctx  context.Context
		err  error
		want errs.Kind
	}{
		{cancelled, errors.New("x"), errs.Interrupted},
		{bg, context.Canceled, errs.Interrupted},
		{bg, ErrNewerSchema, errs.Conflict},
		{bg, errNegativeVersion, errs.Conflict},
		{bg, errs.New(errs.Usage, "op", "m"), errs.Usage},
		{bg, errors.New("other"), errs.Internal},
	} {
		if got := errs.KindOf(wrap(tc.ctx, tc.err, "op", "p")); got != tc.want {
			t.Errorf("wrap(%v) kind %v, want %v", tc.err, got, tc.want)
		}
	}
}
